      const interp = (P, y) => { if (y <= P[0][0]) return P[0].slice(1); for (let i = 1; i < P.length; i++) if (y <= P[i][0]) { const a = P[i - 1], b = P[i], k = (y - a[0]) / (b[0] - a[0]); return [1, 2, 3].map(j => a[j] + (b[j] - a[j]) * k); } return P[P.length - 1].slice(1); };
