      for (let x0 = 0; x0 < 512; x0 += 8 + R() * 18) { xv.beginPath(); xv.moveTo(x0, -1); xv.lineTo(x0 + 4 + R() * 6, 6 + R() * 26); xv.lineTo(x0 + 12 + R() * 8, -1); xv.fill(); }
