      const qSup = segBraco(.56, .036, .029, [[.82, .04]]), qInf = segBraco(.6, .03, .021, [[.3, .025], [.88, .06]]);
      const qSupL = segBraco(.74, .04, .032, [[.5, .035], [.85, .04]]), qInfL = segBraco(.78, .033, .024, [[.9, .07]]);
      const qCot = guardar(new T.SphereGeometry(.036, 8, 6));
