        const sup = new T.Mesh(o.longo ? qSupL : qSup, [mPele, mOuro]), inf = new T.Mesh(o.longo ? qInfL : qInf, [mPele, mOuro]), mao = new T.Mesh(o.longo ? qMaoG : qMao, [mPele, mOuro]), cot = new T.Mesh(qCot, mPele);
