      const tMecha = aniso(K.tex(cm)), tMechaR = aniso(K.tex(cr));
      const mJuba = mat({ mapa: tMecha, rMapa: tMechaR, bump: tMechaR, bs: .25, r: 1, me: .08, vc: true });
