      const ESP = [[-1.32, .8, .1, .1], [-1.1, .86, .3, .3], [-.65, 1.0, .42, .42], [-.1, 1.26, .5, .52], [.35, 1.42, .55, .52], [.8, 1.18, .42, .44]];
