      malha(rabo, tubo([[0, .02, .05], [0, -.1, -.14], [0, -.28, -.2], [0, -.42, -.18]], [[.14, .13], [.1, .09], [.05, .045], [.02, .02]], { nr: 10, nl: 10, ref: [1, 0, 0], ruido: .05, cor: tomPele(.2), fim: .8 }), mPele);
      /* ---------- pescoço grosso e cabeça larga e baixa ---------- */
