          dente(x, .0 + fr * .05, z, Math.sin(a) * .5 + (r2() - .5) * .8, fr * .4 + (r2() - .5) * .7, quebrado ? l * .5 : l, .018 + r2() * .012, (r2() - .5) * .5);
