      const ruido = (x, y, z, k = 0) => Math.sin(1.7 * x + 1.3 * y + k) * Math.sin(1.9 * y - 1.1 * z + 2 * k) * Math.sin(1.3 * z + .7 * x + 3 * k)
        + .5 * Math.sin(3.1 * x - 2.3 * z + k) * Math.sin(2.9 * y + 1.7 * x - k);
