      grupos.forEach((lista, m) => { const geo = U.mergeBufferGeometries(lista); lista.forEach(g => g.dispose()); if (geo) malha(out, geo, m); });
      if (raiz.parent) { raiz.parent.add(out); raiz.parent.remove(raiz); }
