      ref.updateWorldMatrix(true, true); const qr = ref.getWorldQuaternion(new T.Quaternion()), qp = obj.parent.getWorldQuaternion(new T.Quaternion());
      obj.quaternion.copy(qp.invert().multiply(qr).multiply(tmp.quaternion));
