        if (Math.abs(v.x) > .2 && v.y > -.3 && v.y < .3) { const d0 = Math.hypot(v.x, v.z) || 1, c = .014 * Math.max(0, Math.sin(v.y * 50)); v.x += v.x / d0 * c; v.z += v.z / d0 * c; }
