      const fios = []; [[-.05, -.15], [.035, -.17], [.0, -.16]].forEach(([x0, y0], i) => { const L = .15 + i * .1; fios.push(tubo([V(x0, y0, .16), V(x0 * 1.2, y0 - L * .5, .19), V(x0, y0 - L, .17)], t => .006 - t * .003, 10, 5)); });
      const baba1 = malha(juntar(fios), baba, cab);
      // olhinhos no alto da cabeça
