          const L = pol ? .25 : .5 + R() * .12, ondula = (R() - .5) * .04;
          malha(tubo([V(0, 0, 0), V(ondula, -L * .3, .02), V(-ondula, -L * .6, .04), V(ondula * .5, -L * .9, .05), V(0, -L, .1)], t => .013 - t * .007 + Math.max(0, Math.sin(t * Math.PI * 3)) * .003, 20, 6), pele, d);
