      const eOlho = olhoM.emissiveIntensity, eOlhinho = olhinho.emissiveIntensity, FRENTE = new T.Vector3(0, 1.1, 3.5);
      const acao = tipo => { if (tipo === 'ataque' || tipo === 'revelar') acA = { tipo, t: 0, dur: tipo === 'ataque' ? 1.4 : 1.9 }; };
