          Pp.p.rotation.x = a * .3; Pp.joe.rotation.x = Math.max(0, -a) * .12; Pp.pe.rotation.x = -a * .1;
          Pm.p.rotation.x = -a * .42; Pm.joe.rotation.x = Math.max(0, a) * .75; Pm.pe.rotation.x = a * .2;
